# The two rates known on 2026-10-27, recorded so the configuration starts from the
# numbers actually in use rather than from a hidden constant in code. Both rows are
# editable in the UI: Transit Rates under Accounting in the Sidekick menu.
#
# 1.20 is the standard rate that the 2026-07-13 transit reports were priced at.
# 0.65 is the rate stated by the NREN team for Alberta Health Services.
#
# Seed rows are only created when the table is empty, so re-running a migration on a
# database that already has rates cannot overwrite a negotiated figure.
SEED_RATES = [
    (None, decimal.Decimal('1.2000'), 'Standard member transit rate'),
    ('alberta-health-services', decimal.Decimal('0.6500'), 'Negotiated rate for Alberta Health Services'),
]


def seed_rates(apps, schema_editor):
    TransitRate = apps.get_model('sidekick', 'TransitRate')
    Tenant = apps.get_model('tenancy', 'Tenant')

    if TransitRate.objects.exists():
        return

    for slug, rate, comment in SEED_RATES:
        tenant = None
        if slug is not None:
            tenant = Tenant.objects.filter(slug=slug).first()
            if tenant is None:
                # A database without that member still gets the global default.
                continue
        TransitRate.objects.create(
            tenant=tenant,
            rate_per_mbit=rate,
            comments=comment,
        )


def unseed_rates(apps, schema_editor):
    TransitRate = apps.get_model('sidekick', 'TransitRate')
    TransitRate.objects.filter(
        rate_per_mbit__in=[decimal.Decimal('1.2000'), decimal.Decimal('0.6500')]
    ).delete()


